final class NativeRampPartHostChecks {
 private static final BlockPos POS=new BlockPos(22888,100,22888),BAD=POS.east();private static final UUID ID=UUID.fromString("a4d98a75-4718-4dbb-9491-e0e165430009");private static Fixture block;private static BlockEntityType<NativeRampPartEntity> type;private static int checks;
 private static void need(boolean ok,String text){checks++;if(!ok)throw new AssertionError("Ramp part host: "+text);}
 private static final class Fixture extends BaseEntityBlock {Fixture(){super(BlockBehaviour.Properties.of());}protected MapCodec<Fixture> codec(){return MapCodec.unit(this);}public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new NativeRampPartEntity(type,pos,state);}}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!System.getProperty("vandorlabs.transmitterPhase","").startsWith("ramp-host-"))return;var id=ResourceLocation.parse("vandorlabs:ramp_part_host_fixture");event.register(Registries.BLOCK,h->{block=new Fixture();h.register(id,block);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeRampPartEntity>of((p,s)->new NativeRampPartEntity(type,p,s),block).build(null);h.register(id,type);});}}
 private static NativeRampPartData data(BlockPos pos){var state=Blocks.STONE.defaultBlockState();var material=new NativeRampPartMaterial(state,-1,-1,-1,0,false,false,new int[]{-1,-1,-1,-1,-1,-1});var origin=new NativeRampPartData.Origin(pos,8,material);var spec=new NativeRampGeometry.Spec(pos,Direction.NORTH,pos.getY(),0,3,8,0,1,0,-2,false,0,false,false,0,false,false,false,List.of(origin.geometry()));return new NativeRampPartData(spec,state,List.of(origin),new NativeRampPartData.Motion(5,100,0,1,32,true,0));}
 private static CompoundTag envelope(BlockPos pos){var tag=new CompoundTag();tag.putInt("NativeRampPartSchema",1);tag.putUUID("Operation",ID);tag.putInt("RootX",pos.getX());tag.putInt("RootY",pos.getY());tag.putInt("RootZ",pos.getZ());tag.put("NativeRampPartData",data(pos).write());return tag;}
 static void write(ServerLevel level){level.getChunkAt(POS);level.setBlock(POS,block.defaultBlockState(),18);var owner=(NativeRampPartEntity)level.getBlockEntity(POS);owner.loadWithComponents(envelope(POS),level.registryAccess());need(owner.ownershipKnown()&&owner.publication()!=null,"valid complete owner");owner.installPart(ID,POS,data(POS));var initial=owner.publication();try{owner.installPart(ID,POS.above(65),data(POS));throw new AssertionError("far root installed");}catch(IllegalArgumentException expected){}need(owner.publication()==initial&&owner.belongs(ID,POS),"refused installation preserves complete prior owner");owner.prepare(116);var value=owner.publication();need(value.pose()==.5,"authoritative midpoint");need(value.geometry().pieces().stream().map(p->p.box().move(POS)).toList().equals(owner.physicalBounds()),"world collision projection");need(java.util.concurrent.CompletableFuture.supplyAsync(()->owner.publication()==value&&owner.physicalBounds()==value.worldBoxes()).join(),"worker consumes immutable projection");java.util.concurrent.CompletableFuture.runAsync(()->owner.prepare(132)).join();need(owner.publication()==value,"worker refuses authoritative preparation");var dto=owner.getUpdateTag(level.registryAccess());need(dto.contains("NativeRampPartData")&&!dto.contains("Sources")&&!dto.contains("Items"),"public projection excludes physical ownership");level.setBlock(BAD,block.defaultBlockState(),18);var bad=(NativeRampPartEntity)level.getBlockEntity(BAD);var tag=envelope(BAD);tag.getCompound("NativeRampPartData").putInt("Schema",99);tag.putString("OpaquePart","retained");bad.loadWithComponents(tag,level.registryAccess());need(!bad.ownershipKnown()&&bad.publication()==null&&bad.physicalBounds()==null,"failed geometry cannot advertise known ownership");need(bad.saveWithoutMetadata(level.registryAccess()).equals(tag),"exact failed body retention");System.out.println("[vandorlabs][ramp-part-host] write PASS checks="+checks);}
 static void read(ServerLevel level){var owner=(NativeRampPartEntity)level.getBlockEntity(POS);need(owner!=null&&owner.ownershipKnown()&&owner.data()!=null,"part restart");var bad=(NativeRampPartEntity)level.getBlockEntity(BAD);need(bad!=null&&!bad.ownershipKnown()&&bad.publication()==null&&bad.saveWithoutMetadata(level.registryAccess()).getString("OpaquePart").equals("retained"),"inert restart retention");System.out.println("[vandorlabs][ramp-part-host] read PASS checks="+checks);}
}
